151: -- Paradox modifier.  This dictates paradox cost and spellpower scaling
152: -- Note that 300 is the optimal balance
153: -- Caps at -50% and +50%
154: getParadoxModifier = function (self)
155: 	local paradox = self:getParadox()
156: 	local pm = math.sqrt(paradox / 300)
157: 	if paradox < 300 then pm = paradox/300 end
158: 	pm = util.bound(pm, 0.5, 1.5)
159: 	return pm
160: end
161: 
162: -- Paradox cost (regulates the cost of paradox talents)
163: getParadoxCost = function (self, t, value)
164: 	local pm = getParadoxModifier(self)
165: 	local multi = 1
166: 	if self:attr("paradox_cost_multiplier") then
167: 		multi = 1 - self:attr("paradox_cost_multiplier")
168: 	end
169: 	return (value * pm) * multi
170: end
171: 
172: -- Paradox Spellpower (regulates spellpower for chronomancy)
